const DkshProgram *dksh_program(const char *name) {
    for (std::size_t i = 0; i < kDkshProgramCount; ++i)
        if (std::strcmp(kDkshPrograms[i].name, name) == 0) return &kDkshPrograms[i];
    return nullptr;
}

